sealed class ListenerApp:IDisposable {
 readonly Application app;readonly UserNotificationListener listener;readonly CancellationTokenSource stop=new CancellationTokenSource();readonly SemaphoreSlim changed=new SemaphoreSlim(0,1);readonly object gate=new object();readonly JavaScriptSerializer json=new JavaScriptSerializer{MaxJsonLength=4194304};
 readonly DispatcherTimer debounce=new DispatcherTimer{Interval=TimeSpan.FromMilliseconds(250)};readonly Dictionary<uint,NotificationItem> active=new Dictionary<uint,NotificationItem>();bool busy,pending,disposed;string sourceStatus="Windows companion connecting...";string latest="notification-sync:{\"status\":\"Windows companion connecting...\"}";readonly string token;Window permission;TextBlock status;
 readonly Dictionary<string,string> icons=new Dictionary<string,string>();
 readonly Windows.Foundation.TypedEventHandler<UserNotificationListener,UserNotificationChangedEventArgs> handler;
 public ListenerApp(Application app,string pack){this.app=app;var text=File.ReadAllText(Path.Combine(pack,"bridge-tokens.json"));var match=Regex.Match(text,"\"center\"\\s*:\\s*\"([0-9a-f]{64})\"");if(!match.Success)throw new IOException("Bridge token is unavailable");token=match.Groups[1].Value;listener=UserNotificationListener.Current;handler=(sender,args)=>Schedule();listener.NotificationChanged+=handler;debounce.Tick+=async delegate{debounce.Stop();await Sync();};}
 public void Start(bool interactive){var worker=Task.Run((Func<Task>)Connect);if(interactive)ShowPermission();else Schedule();}
 public void Schedule(){if(!disposed&&!app.Dispatcher.HasShutdownStarted)app.Dispatcher.BeginInvoke(new Action(()=>{if(disposed)return;debounce.Stop();debounce.Start();}));}
 string AccessMessage(UserNotificationListenerAccessStatus access){return access==UserNotificationListenerAccessStatus.Denied?"Windows notification access is denied. Allow Nord Rice Notifications in Windows settings, then reconnect.":"Windows notification access has not been granted. Click Connect Windows and allow access.";}
 void Publish(string state,NotificationItem[] items=null){object batch=items==null?(object)new{status=state}:new{status=state,items};string message="notification-sync:"+json.Serialize(batch);lock(gate){sourceStatus=state;if(latest==message)return;latest=message;if(changed.CurrentCount==0)changed.Release();}}
 async Task Sync(){if(disposed)return;if(busy){pending=true;return;}busy=true;try{var access=listener.GetAccessStatus();if(access!=UserNotificationListenerAccessStatus.Allowed){Publish(AccessMessage(access));return;}var notifications=await Await(listener.GetNotificationsAsync(NotificationKinds.Toast));if(disposed)return;var items=new List<NotificationItem>();int iconBudget=1048576;foreach(var notification in notifications.OrderByDescending(n=>n.CreationTime).Take(500))try{var binding=notification.Notification.Visual.GetBinding(KnownNotificationBindings.ToastGeneric);if(binding==null)continue;var texts=binding.GetTextElements().Select(t=>t.Text??"").ToArray();if(texts.Length==0)continue;var appId=notification.AppInfo.AppUserModelId;var created=notification.CreationTime.UtcDateTime;var icon=await AppIcon(notification);if(icon!=null){if(icon.Length>iconBudget)icon=null;else iconBudget-=icon.Length;}items.Add(new NotificationItem{Id="windows:"+appId+":"+notification.Id+":"+created.Ticks,Provider="windows",Source=Limit(notification.AppInfo.DisplayInfo.DisplayName,128),Title=Limit(texts[0],512),Body=Limit(String.Join("\n",texts.Skip(1)),4096),AppId=appId,NativeId=notification.Id,CreatedUtc=created,AppIcon=icon});}catch{}
   active.Clear();foreach(var item in items)active[item.NativeId]=item;Publish("Windows notifications connected",items.ToArray());
  }catch(Exception ex){Publish("Windows notifications unavailable (0x"+ex.HResult.ToString("X8")+"). Reconnect or reinstall the companion.");}finally{busy=false;if(pending){pending=false;Schedule();}}}
 // App logos only: the public listener does not expose sender-profile images.
 async Task<string> AppIcon(UserNotification notification){
  string id=notification.AppInfo.AppUserModelId,value;if(icons.TryGetValue(id,out value))return value;
  value=null;try{using(var stream=await Await(notification.AppInfo.DisplayInfo.GetLogo(new Windows.Foundation.Size(128,128)).OpenReadAsync()))using(var reader=new Windows.Storage.Streams.DataReader(stream.GetInputStreamAt(0))){
   if(stream.Size>1048576)return null;await Await(reader.LoadAsync((uint)stream.Size));var bytes=new byte[(int)stream.Size];reader.ReadBytes(bytes);using(var input=new MemoryStream(bytes)){
   var bitmap=new BitmapImage();bitmap.BeginInit();bitmap.CacheOption=BitmapCacheOption.OnLoad;bitmap.DecodePixelWidth=128;bitmap.StreamSource=input;bitmap.EndInit();bitmap.Freeze();
   foreach(int size in new[]{128,96,64}){BitmapSource logo=bitmap;if(bitmap.PixelWidth>size||bitmap.PixelHeight>size){double factor=(double)size/Math.Max(bitmap.PixelWidth,bitmap.PixelHeight);logo=new TransformedBitmap(bitmap,new ScaleTransform(factor,factor));logo.Freeze();}var encoder=new PngBitmapEncoder();encoder.Frames.Add(BitmapFrame.Create(logo));using(var output=new MemoryStream()){encoder.Save(output);if(output.Length<=24576){value=Convert.ToBase64String(output.ToArray());break;}}}
  }}}catch{}if(value!=null&&icons.Count<128)icons[id]=value;return value;
 }
 static string Limit(string value,int max){value=value??"";return value.Substring(0,Math.Min(value.Length,max));}
 public void ShowPermission(){if(disposed)return;if(permission!=null){permission.Activate();return;}var panel=new StackPanel{Margin=new Thickness(22)};panel.Children.Add(new TextBlock{Text="Windows notifications",FontSize=22,FontWeight=FontWeights.SemiBold});panel.Children.Add(new TextBlock{Text="Allow Nord Rice to read notifications shown by Windows. Your inbox stays on this PC. Dismissal removes only the notifications you choose.",TextWrapping=TextWrapping.Wrap,Margin=new Thickness(0,12,0,14)});status=new TextBlock{Text=AccessMessage(listener.GetAccessStatus()),TextWrapping=TextWrapping.Wrap,FontSize=12,Margin=new Thickness(0,0,0,14)};panel.Children.Add(status);var connect=new Button{Content="Allow Windows access",Padding=new Thickness(12,8,12,8),HorizontalAlignment=HorizontalAlignment.Left};panel.Children.Add(connect);permission=new Window{Title="Nord Rice Notifications",Width=460,SizeToContent=SizeToContent.Height,ResizeMode=ResizeMode.NoResize,WindowStartupLocation=WindowStartupLocation.CenterScreen,Background=new SolidColorBrush(Color.FromRgb(35,42,53)),Foreground=Brushes.White,Content=panel};permission.Closed+=delegate{permission=null;};connect.Click+=async delegate{connect.IsEnabled=false;try{var access=await Await(listener.RequestAccessAsync());if(access==UserNotificationListenerAccessStatus.Allowed){if(permission!=null)permission.Close();await Sync();}else{status.Text=AccessMessage(access);Publish(status.Text);}}catch(Exception ex){status.Text="Access request failed (0x"+ex.HResult.ToString("X8")+").";}finally{connect.IsEnabled=true;}};permission.Show();if(listener.GetAccessStatus()==UserNotificationListenerAccessStatus.Allowed){permission.Close();Schedule();}}
 async Task Connect(){while(!stop.IsCancellationRequested){using(var socket=new ClientWebSocket())using(var connection=CancellationTokenSource.CreateLinkedTokenSource(stop.Token)){try{socket.Options.Proxy=null;using(var timeout=CancellationTokenSource.CreateLinkedTokenSource(stop.Token)){timeout.CancelAfter(4000);await socket.ConnectAsync(new Uri("ws://127.0.0.1:6138/"+token),timeout.Token);}await Send(socket,"subscribe",connection.Token);var sending=SendLoop(socket,connection.Token);Schedule();var receiving=ReadLoop(socket,connection.Token);await Task.WhenAny(sending,receiving);connection.Cancel();socket.Abort();try{await Task.WhenAll(sending,receiving);}catch{}}catch{}finally{connection.Cancel();}}try{await Task.Delay(2000,stop.Token);}catch{break;}}}
 async Task SendLoop(ClientWebSocket socket,CancellationToken token){string sent=null;while(!token.IsCancellationRequested){string message;lock(gate)message=latest;if(message!=sent){await Send(socket,message,token);sent=message;}if(!await changed.WaitAsync(15000,token)){Dispatch(()=>{try{var access=listener.GetAccessStatus();if(access!=UserNotificationListenerAccessStatus.Allowed)Publish(AccessMessage(access));}catch{Publish("Windows notification access is unavailable. Click Connect Windows.");}});string state;lock(gate)state=sourceStatus;await Send(socket,"notification-sync:"+new JavaScriptSerializer().Serialize(new{status=state}),token);}}}
 async Task ReadLoop(ClientWebSocket socket,CancellationToken token){var buffer=new byte[8192];while(!token.IsCancellationRequested){using(var stream=new MemoryStream()){WebSocketReceiveResult result;do{result=await socket.ReceiveAsync(new ArraySegment<byte>(buffer),token);if(result.MessageType==WebSocketMessageType.Close)return;stream.Write(buffer,0,result.Count);if(stream.Length>16777216)throw new IOException();}while(!result.EndOfMessage);if(result.MessageType!=WebSocketMessageType.Text)continue;var payload=Encoding.UTF8.GetString(stream.ToArray());if(payload.IndexOf("notificationAction",StringComparison.Ordinal)<0)continue;try{var root=new JavaScriptSerializer{MaxJsonLength=16777216}.Deserialize<Dictionary<string,object>>(payload);object value;if(!root.TryGetValue("notificationAction",out value))continue;var command=value as Dictionary<string,object>;if(command==null||Convert.ToString(command["action"])!="dismiss")continue;uint id=Convert.ToUInt32(command["id"]);string key=Convert.ToString(command["key"]);Dispatch(new Action(()=>{NotificationItem item;if(!disposed&&listener.GetAccessStatus()==UserNotificationListenerAccessStatus.Allowed&&active.TryGetValue(id,out item)&&item.Id==key){try{var current=listener.GetNotification(id);if(current!=null&&"windows:"+current.AppInfo.AppUserModelId+":"+id+":"+current.CreationTime.UtcDateTime.Ticks==key){listener.RemoveNotification(id);Schedule();}}catch{}}}));}catch{}}}}
 void Dispatch(Action action){if(!disposed&&!app.Dispatcher.HasShutdownStarted)app.Dispatcher.BeginInvoke(action);}
 static Task Send(ClientWebSocket socket,string text,CancellationToken token){return socket.SendAsync(new ArraySegment<byte>(Encoding.UTF8.GetBytes(text)),WebSocketMessageType.Text,true,token);}
 static Task<T> Await<T>(Windows.Foundation.IAsyncOperation<T> operation){var done=new TaskCompletionSource<T>();operation.Completed=(op,state)=>{try{if(state==Windows.Foundation.AsyncStatus.Completed)done.TrySetResult(op.GetResults());else if(state==Windows.Foundation.AsyncStatus.Canceled)done.TrySetCanceled();else done.TrySetException(op.ErrorCode??new Exception("Windows notification operation failed"));}catch(Exception ex){done.TrySetException(ex);}};return done.Task;}
 public void Dispose(){if(disposed)return;disposed=true;stop.Cancel();debounce.Stop();listener.NotificationChanged-=handler;if(permission!=null)permission.Close();}
}
static class ListenerProgram {
 [STAThread]static void Main(string[] args){bool created;using(var mutex=new Mutex(true,"Local\\NordNotificationListener",out created))using(var signal=new EventWaitHandle(false,EventResetMode.AutoReset,"Local\\NordNotificationConnect")){if(!created){if(Array.IndexOf(args,"--background")<0)signal.Set();return;}try{var pack=File.ReadAllText(Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"bridge-location.txt")).Trim();var app=new Application{ShutdownMode=ShutdownMode.OnExplicitShutdown};using(var owner=new ListenerApp(app,pack)){var wait=ThreadPool.RegisterWaitForSingleObject(signal,(state,timeout)=>{if(!app.Dispatcher.HasShutdownStarted)app.Dispatcher.BeginInvoke(new Action(owner.ShowPermission));},null,Timeout.Infinite,false);app.Exit+=delegate{owner.Dispose();wait.Unregister(null);};owner.Start(Array.IndexOf(args,"--background")<0);app.Run();}}catch(Exception ex){if(Array.IndexOf(args,"--background")<0)MessageBox.Show("Notification companion could not start: "+ex.Message,"Nord Rice Notifications");}}}
}
